phylogeny = True

protein_families = ["PF00004"]
models_list = ["MSA-1b","MSA-1b-finetuned-PF00004"]
proposal_types = ["msa_prob_dist","random"]
context_types = ["static","dynamic"]
context_sizes = ["10"]
context_sampling_methods = ["greedy","random"]

scores_folders_common_path = "./scores/msa-seed-simulations/"
msas_folders_common_path = "./data/msa-seed-simulations/"

scores_folders = []
tool_types = []
msas_folders = []

for model in models_list:
    
  scores_path_model = scores_folders_common_path + f"{model}/"
  msas_path_model = msas_folders_common_path + f"{model}/"

  for proposal in proposal_types:
      
    scores_path_proposal = scores_path_model + f"{proposal}-proposal/"
    msas_path_proposal = msas_path_model + f"{proposal}-proposal/"

    for context in context_types:
        
      scores_path_context = scores_path_proposal + f"{context}-context/"
      msas_path_context = msas_path_proposal + f"{context}-context/"

      for context_size in context_sizes:
          
        scores_path_size = scores_path_context + f"{context_size}/"
        msas_path_size = msas_path_context + f"{context_size}/"

        if context == "dynamic":
            
          for context_sampling_method in context_sampling_methods:
                
            scores_path_sampling = scores_path_size + f"{context_sampling_method}/"
            msas_path_sampling = msas_path_size + f"{context_sampling_method}/"

            for family in protein_families:
                  
              scores_path_final = scores_path_sampling + f"{family}"
              scores_folders.append(scores_path_final)

              msas_path_final = msas_path_sampling + f"{family}"
              msas_folders.append(msas_path_final)

              tool_type = f"{model}-{proposal}prop-{context}-{context_sampling_method}-{context_size}"
              tool_types.append(tool_type)


        elif context == "static":

          for family in protein_families:
                  
            scores_path_final = scores_path_size + f"{family}"
            scores_folders.append(scores_path_final)

            msas_path_final = msas_path_sampling + f"{family}"
            msas_folders.append(msas_path_final)
            
            tool_type = f"{model}-{proposal}prop-{context}-{context_size}"
            tool_types.append(tool_type)


