phylogeny = False

protein_families = ["PF00004"]
n_sequences_list = ["50"]
n_mutations_list = ["500"]
models_list = ["MSA-1b","MSA-1b-finetuned-PF00004"]
init_seqs = ["-1"]
proposal_types = ["msa_prob_dist"]
context_sizes = ["10"]

scores_folders_common_path = "./scores/no-phylogeny/"
msas_folders_common_path = "./data/no-phylogeny/"

scores_folders = []
tool_types = []
msas_folders = []

for n_mutations in n_mutations_list:

  scores_path_mutations = scores_folders_common_path + f"{n_mutations}/"
  msas_path_mutations = msas_folders_common_path + f"{n_mutations}/"

  for n_sequences in n_sequences_list:

    scores_path_sequences = scores_folders_common_path + f"{n_sequences}/"
    msas_path_sequences = msas_folders_common_path + f"{n_sequences}/"

    for model in models_list:
        
      scores_path_model = scores_folders_common_path + f"{model}/"
      msas_path_model = msas_folders_common_path + f"{model}/"

      for init_seq in init_seqs:

        scores_path_init = scores_path_model + f"init-seq-{init_seq}/"
        msas_path_init = msas_path_model + f"init-seq-{init_seq}/"

        for proposal in proposal_types:
            
          scores_path_proposal = scores_path_init + f"{proposal}-proposal/"
