        sim_array = pd.DataFrame([list(seq) for seq in df["sequence"]]) 
        nat_array = pd.DataFrame([list(seq) for seq in df["corr_nat_seq"]])

        entropy_df = []

        for k in range(sim_array.shape[1]):

            entropy_sim = entropy(sim_array.iloc[:,k].value_counts())
