        self.sample_static_context(self.original_MSA, method = "greedy", context_size = context_size)
        first_sequence_tokens = self.mcmc(Number_of_Mutation = flip_before_start, previous_sequence_tokens = self.init_seq,
                                        proposal = proposal)
    
        if context_type == "static":
            self.mamba_tree_phylo_recur(clade_root, first_sequence_tokens, proposal = proposal)

        elif context_type == "dynamic":
            self.mamba_tree_phylo_recur_dynamic(clade_root, first_sequence_tokens,context_sampling=context_sampling, context_size = context_size, proposal = proposal)

        results = self.phylogeny_MSA.copy()
        self.phylogeny_MSA = []
        self.context = None
        self.init_seq = None
        
        return results
    
