def custom_mi(values_1, values_2, domain = list("-ACDEFGHIKLMNPQRSTVWY"), pseudocount = 1):

    values_1_counts = {}
    values_2_counts = {}
    joint_counts = {}

    for element in domain:

        values_1_counts[element] = len(domain)*pseudocount
        values_2_counts[element] = len(domain)*pseudocount

    for elem_1 in domain:
        for elem_2 in domain:
            joint_counts[(elem_1,elem_2)] = pseudocount

    for i in range(len(values_1)):

        elem_1 = values_1[i]
        elem_2 = values_2[i]
        values_1_counts[elem_1] += 1
        values_2_counts[elem_2] += 1
        joint_counts[(elem_1,elem_2)] += 1

    total_counts = list(values_1_counts.values())
    total_counts = np.sum(total_counts)

    mi = 0

    for elem_1 in domain:
        for elem_2 in domain:
            
            joint_counts_prob = joint_counts[(elem_1,elem_2)] / total_counts
            value_1_prob = values_1_counts[elem_1] / total_counts
            value_2_prob = values_2_counts[elem_2] / total_counts

            if joint_counts > 0:
                mi += joint_counts_prob * np.log(joint_counts_prob/(value_1_prob * value_2_prob))
    
    return mi
