import numpy as np

np.random.seed(3)

pseudocounts = [0,0.5,1]
sampling = "greedy"

fig, axes = plt.subplots(1,1)

input_MSA = "./data/protein-families-msa-full/PF00004_full.fasta"
all_seqs = [(record.description, remove_insertions(str(record.seq))) for record in SeqIO.parse(input_MSA, "fasta")]

greedy_sample = greedy_select(all_seqs, num_seqs=3000)
n_sequences_list = list(range(100, 2100, 100))


for pseudocount in pseudocounts:

    mi_nat_values_mean_list = []

    for a in range(len(n_sequences_list)):

        n_sequences = n_sequences_list[a]

        if sampling == "random":
            sampled_seq_inds = np.random.choice(range(len(all_seqs)), n_sequences, replace=False)
            sampled_seqs = [all_seqs[i] for i in sampled_seq_inds]
        elif sampling == "greedy":
            sampled_seq_inds = np.random.choice(range(len(greedy_sample)), n_sequences, replace=False)
            sampled_seqs = [all_seqs[i] for i in sampled_seq_inds]

        nat_array = pd.DataFrame([list(seq[1]) for seq in sampled_seqs])
        mi_nat_values = []

        for k in range(nat_array.shape[1]):

            for l in range(k + 1, nat_array.shape[1]):

                mi_nat = custom_mi(list(nat_array.iloc[:,k]),list(nat_array.iloc[:,l]), pseudocount=pseudocount)
                mi_nat_values.append(mi_nat)

        mi_nat_values_mean_list.append(np.average(mi_nat_values))

    mi_nat_values_mean_list_random = []

    for a in range(len(n_sequences_list)):

        n_sequences = n_sequences_list[a]

        char_list = list("-ACDEFGHIKLMNPQRSTVWY")
        sampled_seqs = []

        for j in range((n_sequences)):
            rand_char_order = np.random.choice(range(len(char_list)), len(all_seqs[0][1]), replace = True)
            rand_seq = [char_list[i] for i in rand_char_order]
            rand_seq = ''.join(rand_seq)
            sampled_seqs.append((f'seq{j}',rand_seq))

        nat_array = pd.DataFrame([list(seq[1]) for seq in sampled_seqs])
        mi_nat_values = []

        for k in range(nat_array.shape[1]):

            for l in range(k + 1, nat_array.shape[1]):

                mi_nat = custom_mi(list(nat_array.iloc[:,k]),list(nat_array.iloc[:,l]), pseudocount=pseudocount)
                mi_nat_values.append(mi_nat)

        mi_nat_values_mean_list_random.append(np.average(mi_nat_values))

    axes.plot(n_sequences_list, mi_nat_values_mean_list, label = f"natural_pseudo_{pseudocount}")
    axes.plot(n_sequences_list, mi_nat_values_mean_list_random, label = f"random_pseudo_{pseudocount}")
    axes.set_xlabel("Number of sequences")
    axes.set_ylabel("Mean MI over pairs of columns")
    axes.set_title(f"Sampling strategy = {sampling}")
        
plt.legend()
plt.savefig(f'MI_with_pseudocounts_{sampling}.png')
