from math import floor,ceil
import matplotlib.pyplot as plt

nat_msa_path = "./data/protein-families-msa-seed/PF00004_seed_ordered.fasta"

ncols = 3
nrows = int(ceil((len(tool_types) + 1)/3))

fig, axes = plt.subplots(nrows = nrows, ncols = ncols, figsize = (30,10 * nrows))
sim_ind = 4

for j,folder in enumerate(msas_folders):

    r = floor(j/3)
    c = j % 3
        
    if tool_types[j].startswith("nat"):
        continue
        
    for i,file in enumerate(os.listdir(folder)):

        if not tool_types[j].startswith("nat"):
            file_sim_ind = file.split('.')[0]
            file_sim_ind = int(file_sim_ind.split('-')[1])
        else:
            file_sim_ind = sim_ind

        if file_sim_ind != sim_ind:
            continue

        file_path = os.path.join(folder,file)
        dist_dataframe = pd.DataFrame()

        all_seqs = [(record.description, remove_insertions(str(record.seq))) for record in SeqIO.parse(file_path, "fasta")]
                
        num_sim_array = np.array([list(seq[1]) for seq in all_seqs], dtype=np.bytes_).view(np.uint8)
        distance_matrix_sim = cdist(num_sim_array,num_sim_array, "hamming") 
    
        a = axes[r][c].imshow(distance_matrix_sim,cmap='RdBu', vmin=0, vmax=1)
        axes[r][c].set_title(tool_types[j])

        cbar = fig.colorbar(a, ax=axes[r][c])

all_nat_seqs = [(record.description, remove_insertions(str(record.seq))) for record in SeqIO.parse(nat_msa_path, "fasta")]

num_nat_array = np.array([list(seq[1]) for seq in all_nat_seqs], dtype=np.bytes_).view(np.uint8)
distance_matrix_nat = cdist(num_nat_array,num_nat_array, "hamming")

a = axes[r][c].imshow(distance_matrix_nat,cmap='RdBu', vmin=0, vmax=1)
axes[r][c].set_title(tool_types[j])

cbar = fig.colorbar(a, ax=axes[r][c])

all_seqnames = [record.description for record in SeqIO.parse(nat_msa_path, "fasta")]

patristic_dist_matrix = np.zeros((len(all_seqnames),len(all_seqnames)))
        
for i in range(len(all_seqnames)):
    for j in range(i + 1, len(all_seqnames)):
        patristic_dist_matrix[i][j] = tree.distance(all_seqnames[i], all_seqnames[j])
        patristic_dist_matrix[j][i] = patristic_dist_matrix[i][j]

max_patristic_distance = patristic_dist_matrix.max()
patristic_dist_matrix /= max_patristic_distance

if c == 3:
    r += 1
    c = 0
else:
    c += 1

a = axes[r][c].imshow(patristic_dist_matrix,cmap='RdBu_r')
axes[r][c].set_title("Normalised patristic Distance Matrix for PF00004")

cbar = fig.colorbar(a, ax=axes)

plt.savefig(f"hamming_distance_matrices_sim_{sim_ind}_msa_vs_randomprop.png")

plt.show()
