          msas_path_proposal = msas_path_init + f"{proposal}-proposal/"

          for context_size in context_sizes:
            
            scores_path_size = scores_path_proposal + f"context-size-{context_size}/"

            if not os.path.exists(scores_path_size):
              continue

            msas_path_size = msas_path_proposal + f"context-size-{context_size}/"

            for family in protein_families:
                    
              scores_path_final = scores_path_size + f"{family}"

              if not os.path.exists(scores_path_final):
                continue

              scores_folders.append(scores_path_final)

              msas_path_final = msas_path_size + f"{family}"
              msas_folders.append(msas_path_final)

              if init_seq == "-1":
                init_seq_dummy = "random"
              else:
                init_seq_dummy = init_seq
              
              tool_type = f"{model}-{dummy_proposal}prop-no-phylogeny-size-{context_size}-muts-{n_mutations}-init-seq-{init_seq_dummy}"
              tool_types.append(tool_type)

