phylogeny = True
include_nat = True

protein_families = ["PF00004"]
models_list = ["MSA-1b","ESM2","Potts"]
init_seqs = ["0"]
proposal_types = ["msa_prob_dist","random"]
context_types = ["static","dynamic"]
context_sizes = ["10"]
context_sampling_methods = ["greedy","random"]

scores_folders_common_path = "./scores/msa-seed-simulations/"
msas_folders_common_path = "./data/msa-seed-simulations/"

scores_folders = []
tool_types = []
msas_folders = []

for model in models_list:
    
  scores_path_model = scores_folders_common_path + f"{model}/"

  if not os.path.exists(scores_path_model):
    continue

  msas_path_model = msas_folders_common_path + f"{model}/"

  for init_seq in init_seqs:

    scores_path_init = scores_path_model + f"init-seq-{init_seq}/"

    if not os.path.exists(scores_path_init):
      continue

    msas_path_init = msas_path_model + f"init-seq-{init_seq}/"

    if model in ["ESM2","Potts"]:

      for family in protein_families:
                    
        scores_path_final = scores_path_init + f"{family}"

        if not os.path.exists(scores_path_final):
          continue

        scores_folders.append(scores_path_final)

        msas_path_final = msas_path_init + f"{family}"
        msas_folders.append(msas_path_final)

        tool_types.append(model)
      
      continue

    for proposal in proposal_types:
      
      if proposal == "msa_prob_dist":
        dummy_proposal = "msa"
      else:
        dummy_proposal = proposal

      scores_path_proposal = scores_path_init + f"{proposal}-proposal/"

      if not os.path.exists(scores_path_proposal):
        continue

      msas_path_proposal = msas_path_init + f"{proposal}-proposal/"

      for context in context_types:
          
        scores_path_context = scores_path_proposal + f"{context}-context/"

        if not os.path.exists(scores_path_context):
          continue

        msas_path_context = msas_path_proposal + f"{context}-context/"

        for context_size in context_sizes:
            
          scores_path_size = scores_path_context + f"{context_size}/"

          if not os.path.exists(scores_path_size):
            continue

          msas_path_size = msas_path_context + f"{context_size}/"

          if init_seq == "-1":
            init_seq_dummy = "random"
          else:
            init_seq_dummy = init_seq

          if context == "dynamic":
              
            for context_sampling_method in context_sampling_methods:
                  
              scores_path_sampling = scores_path_size + f"{context_sampling_method}/"

              if not os.path.exists(scores_path_sampling):
                continue

              msas_path_sampling = msas_path_size + f"{context_sampling_method}/"

              for family in protein_families:
                    
                scores_path_final = scores_path_sampling + f"{family}"

                if not os.path.exists(scores_path_final):
                  continue

                scores_folders.append(scores_path_final)

                msas_path_final = msas_path_sampling + f"{family}"
                msas_folders.append(msas_path_final)

                tool_type = f"{model}-{dummy_proposal}prop-{context}-{context_sampling_method}-{context_size}-init-seq-{init_seq_dummy}"
                tool_types.append(tool_type)


          elif context == "static":

            for family in protein_families:
                    
              scores_path_final = scores_path_size + f"{family}"

              if not os.path.exists(scores_path_final):
                continue
              
              scores_folders.append(scores_path_final)

              msas_path_final = msas_path_size + f"{family}"
              msas_folders.append(msas_path_final)
              
              tool_type = f"{model}-{dummy_proposal}prop-{context}-{context_size}-init-seq-{init_seq_dummy}"
              tool_types.append(tool_type)

if include_nat:
  for family in protein_families:
    nat_scores_path = "./scores/protein-families-msa-seed/" 
    scores_folders.append(nat_scores_path)

    nat_msas_path = "./data/protein-families-msa-seed/"
    msas_folders.append(msas_path_final)
   
    tool_type = f"nat-{family}"
    tool_types.append(tool_type) 

tree_path = "./data/seed-trees/PF00004_seed.newick"
