family = "PF00005"
sim_ind = 1
tool = "MSA-1b-logitsprop-static-10-init-seq-0"

families = list(all_metrics_dataframe["pfam_id"].unique())
sim_inds = list(range(1,11))

model, alphabet = esm.pretrained.esm_msa1b_t12_100M_UR50S()
batch_converter = alphabet.get_batch_converter()
model = model.to(device)
model.eval() 

ncols = 3
nrows = max(2,int(ceil((len(families))/3)))

fig, axes = plt.subplots(nrows = nrows, ncols = ncols, figsize = (30,10 * nrows))

for k, sim_ind in enumerate(sim_inds):

    all_metrics_dataframe_fam = all_metrics_dataframe.loc[(all_metrics_dataframe["pfam_id"] == family) & 
                                                      (all_metrics_dataframe["sim_ind"] == sim_ind) &
                                                      (all_metrics_dataframe["tool"] == tool), :].reset_index(drop = True)

    i = floor(k/3)
    j = k % 3

    sequences = [(name, seq) for name, seq in zip(all_metrics_dataframe_fam["sequence_name"], all_metrics_dataframe["sequence"])]
    device = "cuda:1" if torch.cuda.is_available() else "cpu"

    _,_, sequences_tensor = batch_converter([sequences])
    sequences_tensor = sequences_tensor.to(device)

    model_output = model(sequences_tensor, need_head_weights=True)
    column_attns = model_output["col_attentions"][0]

    n_seqs = column_attns.shape[-1]
    a = torch.mean(column_attns, axis = [3])
    a = torch.mean(a, axis = [2]).cpu().numpy()
    a = np.reshape(a, newshape = (-1,n_seqs), order = 'C')
    a = np.transpose(a)

    a_df = pd.DataFrame(a, columns = [f"col_attn_{i}" for i in range(a.shape[1])])
    final_df = pd.concat([a_df, all_metrics_dataframe_fam], axis = 1)

    corr_matrix = np.zeros(144)

    for i in range(len(corr_matrix)):

        corr = pearsonr(final_df[f"col_attn_{i}"], final_df["stat_energy_scores"]).statistic
        corr_matrix[i] = corr

    corr_matrix = np.reshape(corr_matrix, newshape = (12,12), order = "C")

    axes[i][j].imshow(corr_matrix, vmin = -1, vmax = 1, cmap = "RdBu_r")
    axes[i][j].colorbar()
