all_distances_dataframe = pd.read_csv("./all_distances_all_sims_all_models_all_families.tsv", delimiter = "\t")

statistics_table = []

for tool in list(all_distances_dataframe["tool"].unique()):
    for family in protein_families:
            for sim_ind in list(range(1,11)):
                all_distances_dataframe_fam = all_distances_dataframe.loc[(all_distances_dataframe["pfam_id"] == family) & 
                                                                (all_distances_dataframe["sim_ind"] == sim_ind) &
                                                                (all_distances_dataframe["tool"] == tool), :].reset_index(drop = True)


                pearson_corr = pearsonr(all_distances_dataframe_fam["ham_dist_sim"], all_distances_dataframe_fam["ham_dist_corr_nat"])
                lin_fit = stats.linregress(all_distances_dataframe_fam["ham_dist_sim"], all_distances_dataframe_fam["ham_dist_corr_nat"])
                statistics_table.append({"family":family,"tool":tool,"sim_ind":sim_ind, "corr":pearson_corr.statistic, "slope":lin_fit.slope, "intercept":lin_fit.intercept})

statistics_table = pd.DataFrame(statistics_table)
