all_distances_dataframe = pd.read_csv("./all_distances_all_sims_all_models_all_families.tsv", delimiter = "\t")

statistics_table = []

for tool in list(all_distances_dataframe["tool"].unique()):
    for family in protein_families:
            for sim_ind in list(range(1,2)):
                all_distances_dataframe_fam = all_distances_dataframe.loc[(all_distances_dataframe["family"] == family) & 
                                                                (all_distances_dataframe["sim_ind"] == sim_ind) &
                                                                (all_distances_dataframe["tool"] == tool), :].reset_index(drop = True)

                try:
                    hd_pearson_corr = pearsonr(all_distances_dataframe_fam["hd_sim"], all_distances_dataframe_fam["corr_patristic_dist"])
                    hd_lin_fit = stats.linregress(all_distances_dataframe_fam["hd_sim"], all_distances_dataframe_fam["corr_patristic_dist"])
                except:
                    continue

                uncorrected_fd_pearson_corr = pearsonr(all_distances_dataframe_fam["uncorrected_fd_sim"], all_distances_dataframe_fam["corr_patristic_dist"])
                uncorrected_fd_lin_fit = stats.linregress(all_distances_dataframe_fam["uncorrected_fd_sim"], all_distances_dataframe_fam["corr_patristic_dist"])

                corrected_pearson_corr = pearsonr(all_distances_dataframe_fam["corrected_fd_sim"], all_distances_dataframe_fam["corr_patristic_dist"])
                corrected_lin_fit = stats.linregress(all_distances_dataframe_fam["corrected_fd_sim"], all_distances_dataframe_fam["corr_patristic_dist"])

                statistics_table.append({"family":family,"tool":tool,"sim_ind":sim_ind, 
                                         "hd_corr":hd_pearson_corr.statistic, "hd_slope":hd_lin_fit.slope, "hd_intercept":hd_lin_fit.intercept,
                                         "uncorrected_fd_corr":uncorrected_fd_pearson_corr.statistic, "uncorrected_fd_slope":uncorrected_fd_lin_fit.slope, "uncorrected_fd_intercept":uncorrected_fd_lin_fit.intercept,
                                         "corrected_fd_corr":corrected_pearson_corr.statistic, "corrected_fd_slope":corrected_lin_fit.slope, "corrected_fd_intercept":corrected_lin_fit.intercept})

statistics_table = pd.DataFrame(statistics_table)
