from dendropy import Tree, TreeList
from collections import defaultdict

def compute_clade_support(reference_tree_file, bootstrap_tree_files, rooted=False):
    """
    Calculates clade (bipartition) support values from bootstrap trees.
    """
    ref_tree = Tree.get(path=reference_tree_file, schema='newick', rooting='force-unrooted' if not rooted else 'default')
    ref_tree.encode_bipartitions()
    
    bootstrap_trees = TreeList()
    for bt_file in bootstrap_tree_files:
        tree = Tree.get(path=bt_file, schema='newick', rooting='force-unrooted' if not rooted else 'default')
        tree.encode_bipartitions()
        bootstrap_trees.append(tree)

    bipartition_counts = defaultdict(int)
    total_bootstraps = len(bootstrap_trees)

    for tree in bootstrap_trees:
        for edge in tree.postorder_edge_iter():
            bipart = edge.bipartition
            if bipart and not bipart.is_trivial():
                bipartition_counts[bipart] += 1

    support = {}
    for edge in ref_tree.postorder_edge_iter():
        bipart = edge.bipartition
        if bipart and not bipart.is_trivial():
            clade_taxa = bipart.leafset_as_taxon_set()
            support[frozenset(str(t.label) for t in clade_taxa)] = bipartition_counts.get(bipart, 0) / total_bootstraps

    return support
