import dendropy
from collections import Counter

taxon_namespace = dendropy.TaxonNamespace()

# Load and prepare the reference tree
ref_tree = dendropy.Tree.get(
    path=ref_tree_path,
    schema="newick",
    rooting="force-unrooted" if not rooted else "default-rooted",
    taxon_namespace=taxon_namespace
)
ref_tree.encode_bipartitions()

# Load bootstrap trees
bootstrap_trees = []
for f in bootstrap_tree_paths:
    t = dendropy.Tree.get(
        path=f,
        schema="newick",
        rooting="force-unrooted" if not rooted else "default-rooted",
        taxon_namespace=taxon_namespace
    )
    t.encode_bipartitions()
    bootstrap_trees.append(t)

# Count bipartitions across bootstrap trees
bootstrap_splits = Counter()
for tree in bootstrap_trees:
    for edge in tree.postorder_edge_iter():
        bipart = edge.bipartition
        if bipart.is_trivial():
            continue
        bootstrap_splits[bipart.split_bitmask] += 1

# Compute support for bipartitions in reference tree
total = len(bootstrap_trees)
clade_support = {}
for edge in ref_tree.postorder_edge_iter():
    bipart = edge.bipartition
    if bipart.is_trivial():
        continue
    support = bootstrap_splits.get(bipart.split_bitmask, 0) / total
    taxon_set = frozenset(str(t.label) for t in bipart.leafset())
    clade_support[taxon_set] = support
