def get_taxon_sets(tree):
    """
    Returns a set of frozensets representing non-trivial clades (bipartitions)
    based on taxon labels, normalized to avoid complement mismatches.
    """
    tree.encode_bipartitions()
    clades = set()
    taxon_namespace = tree.taxon_namespace
    num_taxa = len(taxon_namespace)
    all_taxa = set(str(t.label) for t in taxon_namespace)

    for edge in tree.postorder_edge_iter():
        bp = edge.bipartition
        if bp.is_trivial():
            continue
        clade_taxa = frozenset(
            str(taxon_namespace[i].label)
            for i in range(num_taxa)
            if bp.split_bitmask & (1 << i)
        )
        # Normalize to always use the smaller side of the bipartition
        if len(clade_taxa) > num_taxa / 2:
            clade_taxa = all_taxa - clade_taxa
        clades.add(frozenset(clade_taxa))
    return clades


taxon_namespace = dendropy.TaxonNamespace()

# Load reference tree
ref_tree = dendropy.Tree.get(
    path=ref_tree_path,
    schema="newick",
    rooting="force-unrooted",
    taxon_namespace=taxon_namespace
)
ref_clades = get_taxon_sets(ref_tree)

# Count how often each clade occurs in bootstrap trees
clade_counter = Counter()
for bs_file in bootstrap_tree_paths:
    bs_tree = dendropy.Tree.get(
        path=bs_file,
        schema="newick",
        rooting="force-unrooted",
        taxon_namespace=taxon_namespace
    )
    bs_clades = get_taxon_sets(bs_tree)
    clade_counter.update(bs_clades)

total_bootstraps = len(bootstrap_tree_files)

# Compute support for each reference clade
clade_support = {
    clade: clade_counter.get(clade, 0) / total_bootstraps
    for clade in ref_clades
}
