    del model_output, sequences_tensor, column_attns
    torch.cuda.empty_cache()

    mean_attn = torch.mean(mean_attn, axis = [2]).cpu().numpy()
    mean_attn = np.reshape(mean_attn, newshape = (-1,n_seqs), order = 'C')
