all_families_df = pd.DataFrame()

corr_matrix_pat_list = []

for k, family in enumerate(families):

    torch.cuda.empty_cache()

    MSA_filename_seed = f"./data/protein-families-msa-seed/{family}_seed.fasta"
    nat_seqs = [(record.description, remove_insertions(str(record.seq))) for record in SeqIO.parse(MSA_filename_seed, "fasta")]

    all_metrics_dataframe_fam = all_metrics_dataframe.loc[(all_metrics_dataframe["family"] == family) & 
                                                      (all_metrics_dataframe["sim_ind"] == sim_ind) &
                                                      (all_metrics_dataframe["tool"] == tool), :].reset_index(drop = True)

    x = floor(k/3)
    y = k % 3


    if len(all_metrics_dataframe_fam) > 500:
        # random_ind = list(np.random.choice(range(len(all_metrics_dataframe_fam)),500, replace = False))
        all_metrics_dataframe_fam = all_metrics_dataframe_fam.iloc[:300, :].reset_index(drop = True)

    sequences = [(name, seq) for name, seq in zip(all_metrics_dataframe_fam["sequence_name"], all_metrics_dataframe_fam["sequence"])]
    device = "cuda:1" if torch.cuda.is_available() else "cpu"

    _,_, sequences_tensor = batch_converter([sequences])
    sequences_tensor = sequences_tensor.to(device)

    model_output = model(sequences_tensor, need_head_weights=True)
    column_attns = model_output["col_attentions"][0]

    column_attns_sym = (column_attns + column_attns.transpose(3,4)) / 2

    del column_attns
    
    n_seqs = len(sequences)
    mean_attn = torch.mean(column_attns_sym, axis = [2]).cpu().numpy()

    del model_output, sequences_tensor, column_attns_sym
    torch.cuda.empty_cache()

    tree_path = f"./data/seed-trees/{family}_seed.newick"
    tree = Phylo.read(tree_path,"newick")
    tree.root_at_midpoint()

    reordered_seqs = reorder_seqs(tree.clade, dict(nat_seqs))
    mapping_dict = {f"seq{i}":reordered_seqs[i][0] for i in range(len(nat_seqs))}
    rows = []

    for i in range(len(sequences)):
        for j in range(i+1, len(sequences)):

            seqname_i = sequences[i][0]
            seqname_j = sequences[j][0]

            if tool != "nat":
                pat_dist = tree.distance(mapping_dict[seqname_i],mapping_dict[seqname_j])
            else:
                pat_dist = tree.distance(seqname_i,seqname_j)

            attn_vals = list(mean_attn[:,:, i, j].flatten())
            row = attn_vals + [pat_dist]
            rows.append(row)

    num_sim_array = np.array([list(seq) for seq in sequences], dtype=np.bytes_).view(np.uint8)
    
    distance_matrix_sim = cdist(num_sim_array,num_sim_array, "hamming")
    pairwise_distances_sim = distance_matrix_sim[np.triu_indices_from(distance_matrix_sim, k=1)]

    pat_dist_df = pd.DataFrame(rows, columns = [f"col_attn_{i}" for i in range(144)] + ["patristic_dist"])
    pat_dist_df["norm_pat_dist"] = pat_dist_df["patristic_dist"]/pat_dist_df["patristic_dist"].max()
    pat_dist_df["ham_dist"] = list(pairwise_distances_sim)
    pat_dist_df["family"] = family
    pat_dist_df["sim_ind"] = sim_ind

    all_families_df = pd.concat([all_families_df, pat_dist_df]).reset_index(drop = True)

    corr_matrix_pat = np.zeros(144)

    for a in range(len(corr_matrix_pat)):

        corr = pearsonr(pat_dist_df[f"col_attn_{a}"], pat_dist_df["patristic_dist"]).statistic
        corr_matrix_pat[a] = corr

    corr_matrix_pat = np.reshape(corr_matrix_pat, newshape = (12,12), order = "C")

    corr_matrix_pat_list.append(corr_matrix_pat)

    im = axes[x][y].imshow(corr_matrix_pat, vmin = -1, vmax = 1, cmap = "RdBu_r")
    plt.colorbar(im, ax=axes[x][y])
    axes[x][y].set_title(f"{family}")
