from scipy.special import expit, logit
from sklearn.linear_model import LinearRegression
from sklearn.compose import TransformedTargetRegressor
from sklearn.model_selection import train_test_split
from sklearn.metrics import r2_score
import statsmodels.api as sm


epsilon = 1e-6

def safe_logit(y):
    y = np.clip(y, epsilon, 1 - epsilon)
    return logit(y)

attention_cols = [f"col_attn_{i}" for i in range(144)]
response_col = "ham_dist"

model_dicts = []

for family in all_families_df["family"].unique():

    all_families_df_fam = all_families_df.loc[all_families_df["family"] == family, :].reset_index(drop = True)

    X = all_families_df_fam[attention_cols].to_numpy()
    y = all_families_df_fam[response_col].to_numpy()

    X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=24)

    # logistic_regressor = TransformedTargetRegressor(regressor=LinearRegression(),
    #                                 func=safe_logit, inverse_func=expit)
    
    # logistic_regressor.fit(X_train, y_train)
    # coefs = logistic_regressor.regressor_.coef_

    formula = f"{response_col} ~ " + " + ".join(attention_cols)
    binom_model = sm.GLM(y_train, X_train, family=sm.families.Binomial())
    binom_model_results = binom_model.fit(maxiter=500, tol=1e-9)

    y_pred = binom_model_results.predict(X_test)
    r2 = r2_score(y_test, y_pred)

    coefs = binom_model_results.params[-12 * 12:].reshape(12, 12),

    model_dicts.append({"family":family, "model_coefs": coefs, "r2_score":r2})
