    mapping_dict = {f"seq{i}":reordered_seqs[i][0] for i in range(len(nat_seqs))}

    train_rows = []

    for i in range(len(train_seqs)):
        for j in range(i+1, len(train_seqs)):

            seqname_i = sequences[i][0]
            seqname_j = sequences[j][0]

            if tool != "nat":
                pat_dist = tree.distance(mapping_dict[seqname_i],mapping_dict[seqname_j])
            else:
                pat_dist = tree.distance(seqname_i,seqname_j)

            attn_vals = list(attns_train[:,:, i, j].flatten())
            row = attn_vals + [pat_dist]
            train_rows.append(row)

    test_rows = []

    for i in range(len(test_seqs)):
        for j in range(i+1, len(test_seqs)):

            seqname_i = sequences[i][0]
            seqname_j = sequences[j][0]

            if tool != "nat":
                pat_dist = tree.distance(mapping_dict[seqname_i],mapping_dict[seqname_j])
            else:
                pat_dist = tree.distance(seqname_i,seqname_j)

            attn_vals = list(attns_test[:,:, i, j].flatten())
            row = attn_vals + [pat_dist]
            test_rows.append(row)

    train_df = pd.DataFrame(train_rows, columns = [f"col_attn_{i}" for i in range(144)] + ["patristic_dist"])
    train_df["norm_pat_dist"] = train_df["patristic_dist"]/train_df["patristic_dist"].max()
    train_df["ham_dist"] = hamming_distances_train
    train_df["family"] = family
