    test_seqs = [sequences[idx] for idx in test_idxs]

    train_tensor = sequences_tensor.clone()[:,train_idxs, :]
    test_tensor = sequences_tensor.clone()[:,test_idxs, :]

    hamming_distances_train = pdist(train_tensor.cpu().numpy()[0, :, 1:], "hamming")
    hamming_distances_test = pdist(test_tensor.cpu().numpy()[0, :, 1:], "hamming")

    attns_train, attns_test = attns_mean_on_cols_symm[:, :, train_idxs, :][:, :, :, train_idxs], attns_mean_on_cols_symm[:, :, test_idxs, :][:, :, :, test_idxs]

    del model_output, sequences_tensor
    torch.cuda.empty_cache()

    tree_path = f"./data/seed-trees/{family}_seed.newick"
