    test_df = pd.DataFrame(test_rows, columns = [f"col_attn_{i}" for i in range(144)] + ["patristic_dist"])
    test_df["norm_pat_dist"] = test_df["patristic_dist"]/test_df["patristic_dist"].max()
    test_df["ham_dist"] = hamming_distances_test
    test_df["family"] = family
    test_df["sim_ind"] = sim_ind

    all_families_train_df = pd.concat([all_families_train_df, train_df]).reset_index(drop = True)
