from torch.utils.data import Dataset, DataLoader
import torch
import torch.nn as nn
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

class AttentionNet(nn.Module):

    def __init__(self, n_layers, hid_dim, drop_prob):

        super().__init__()

        self.n_layers = n_layers
        self.hid_dim = hid_dim
        self.input_layer = nn.Linear(144, hid_dim)
        self.hidden_layers = nn.ModuleList([nn.Linear(hid_dim, hid_dim) for _ in range(self.n_layers)])
        self.output_layer = nn.Linear(hid_dim, 1)
        self.dropout = nn.Dropout(drop_prob)
        self.relu = nn.ReLU()
        self.sigmoid =  nn.Sigmoid()

    def forward(self, x):

        x = self.input_layer(x)
        for layer in self.hidden_layers:
            x = layer(x)
            x = self.relu(x)
            x= self.dropout(x)
        x = self.output_layer(x)
        x = self.sigmoid(x)

        return x
