            init_seq_scores = scores.loc[scores["sequence_name"] == init_seq_id, :].reset_index(drop = True)
            init_seq_scores["Tool"] = f"init-seq-{init_seq}"
            init_seq_scores["Family"] = family
            init_seq_scores["Sim index"] = 1
