from sklearn.metrics import mean_absolute_percentage_error, r2_score
import pickle as pkl
from torcheval.metrics import R2Score

def fit_attention_model_NN(train_df, test_df, seed_number, attention_cols, response_col):

    hidden_size = 1
    num_epochs = 100
    batch_size = 1000
    learning_rate = 0.01
    n_layers = 0
    dropout_prob = 0.2

    train_df_seed = train_df.loc[train_df["seed_number"] == seed_number, :].reset_index(drop = True)
    test_df_seed = test_df.loc[test_df["seed_number"] == seed_number, :].reset_index(drop = True)

    X_train = torch.tensor(train_df_seed[attention_cols].values, dtype=torch.float32)
    y_train = torch.tensor(train_df_seed[response_col].values, dtype=torch.float32)

    X_test = torch.tensor(test_df_seed[attention_cols].values, dtype=torch.float32)
    y_test = torch.tensor(test_df_seed[response_col].values, dtype=torch.float32)

    gpu = int(get_free_gpu())
    device = torch.device(f'cuda:{gpu}' if torch.cuda.is_available() else 'cpu')

    train_dataset = TensorDataset(X_train, y_train)
    test_dataset = TensorDataset(X_test, y_test)

    train_loader = torch.utils.data.DataLoader(dataset=train_dataset, 
                                           batch_size=batch_size, 
                                           shuffle=True)

    test_loader = torch.utils.data.DataLoader(dataset=test_dataset, 
                                          batch_size=batch_size, 
                                          shuffle=False)
    
    model = AttentionNet(len(attention_cols), n_layers, hidden_size, drop_prob=dropout_prob).to(device)

    criterion = nn.MSELoss()
    optimizer = torch.optim.Adam(model.parameters(), lr=learning_rate) 
    scheduler = torch.optim.lr_scheduler.StepLR(optimizer, step_size=50, gamma=0.9)

    for param in model.parameters():
        assert param.requires_grad   

    y_pred_test = []
    y_pred_train = []
    y_test = []
    y_train = []

    n_samples_train = X_train.shape[0]
    n_samples_test = X_test.shape[0]

    n_total_steps = len(train_loader)

    epoch_losses = []
    test_epoch_losses = []

    epoch_mape = []
    test_epoch_mape = []


    for epoch in range(num_epochs):

        batch_losses = []
        mape_batch_losses = []

        model.train()

        for i, (data, labels) in enumerate(train_loader):  

            data = data.to(device)
            labels = labels.to(device)
            
            outputs = model(data).squeeze(1)

            loss = criterion(outputs, labels)
            batch_losses.append(loss.item())

            with torch.no_grad():
                mape = mean_absolute_percentage_error(outputs.cpu().numpy(), labels.cpu().numpy())
                mape_batch_losses.append(mape)

            optimizer.zero_grad()
            loss.backward()
            optimizer.step()
                    
            if (i+1) % 10 == 0:
                print (f'Epoch [{epoch+1}/{num_epochs}], Step [{i+1}/{n_total_steps}], Loss: {loss.item():.4f}')

        # scheduler.step()

        epoch_losses.append(np.mean(batch_losses))
        epoch_mape.append(np.mean(mape_batch_losses))

        model.eval()

        test_batch_losses = []
        test_mape_batch_losses = []

        with torch.no_grad():

            for data, labels in test_loader:

                data = data.to(device)
                labels = labels.to(device)
                outputs = model(data).squeeze(1)

                y_pred_test.append(outputs.cpu().numpy())
                y_test.append(labels.cpu().numpy())

                loss = criterion(outputs, labels)
                test_batch_losses.append(loss.item())

                mape = mean_absolute_percentage_error(outputs.cpu().numpy(), labels.cpu().numpy())
                test_mape_batch_losses.append(mape)

            test_epoch_losses.append(np.mean(test_batch_losses))
            test_epoch_mape.append(np.mean(test_mape_batch_losses))

            for data, labels in train_loader:

                data = data.to(device)
                labels = labels.to(device)
                outputs = model(data).squeeze(1).cpu().numpy()

                y_pred_train.append(outputs)
                y_train.append(labels.cpu().numpy())

    y_pred_test = np.concatenate(y_pred_test)
    y_test = np.concatenate(y_test)
    y_pred_train = np.concatenate(y_pred_train)
    y_train = np.concatenate(y_train)

    y_pred_test = y_pred_test[-n_samples_test:]
    y_test = y_test[-n_samples_test:]
    y_pred_train = y_pred_train[-n_samples_train:]
    y_train = y_train[-n_samples_train:]


    del(model,outputs,optimizer)

    torch.cuda.empty_cache()

    print(len(y_train))

    
    regr_results = ({
        "tool": tool,   
        "family":family, 
        "seed_number":seed_number ,
        "RMSE (training)": np.linalg.norm(y_train - y_pred_train) / np.sqrt(n_samples_train),
        "RMSE (test)": np.linalg.norm(y_test - y_pred_test) / np.sqrt(n_samples_test),
        "MAE (training)": np.sum(np.abs(y_train - y_pred_train)) / len(y_train),
        "MAE (test)": np.sum(np.abs(y_test - y_pred_test)) / len(y_test),
        "R^2 (test)" : r2_score(y_test, y_pred_test),
        "R^2 (train)" : r2_score(y_train, y_pred_train),
        "epoch_losses":epoch_losses,
        "test_epoch_losses":test_epoch_losses,
        "epoch_mape":epoch_mape,
        "test_epoch_mape": test_epoch_mape,
        # "R^2 (small test)" : r2_score(small_test, small_pred_test),
        # "R^2 (large test)" : r2_score(large_test, large_pred_test),
        # "Pearson (test)" : pearsonr(y_test, y_pred_test).statistic
        })
    
    return regr_results
