    scores_folders.append(nat_scores_path)

    scores = pd.read_csv(os.path.join(nat_scores_path, f"{family}_seed.tsv"), delimiter = "\t")
    max_nat_hmmer_score[family] = scores["hmmer_seq_score"].max()
