import numpy as np
import networkx as nx
from ete3 import Tree
from scipy.sparse import csgraph, csr_matrix
from scipy.sparse.linalg import spsolve

def is_float(element: any) -> bool:
    #If you expect None to be passed:
    if element is None: 
        return False
    try:
        float(element)
        return True
    except ValueError:
        return False

def newick_to_graph(newick_str):
    
    """Parse Newick string and convert to NetworkX graph"""
    t = Tree(newick_str, format=1)
    G = nx.Graph()
    idx = {}
    counter = [0]

    def name_nodes(node):
        if node.name == "" or is_float(node.name):
            node.name = f"n{counter[0]}"
            counter[0] += 1
        idx[node.name] = node
        for child in node.children:
            name_nodes(child)

    def add_nodes(node):
        for child in node.children:
            G.add_edge(node.name, child.name)
            add_nodes(child)
    
    name_nodes(t)
    add_nodes(t)
    return G, t

def get_leaf_indices(tree):
    """Return leaf node names and a consistent ordering"""
    return [leaf.name for leaf in tree.iter_leaves()]

def compute_dirichlet_embedding(G, leaf_names, H_leaf_dict):
    """Compute Dirichlet embeddings on the tree given tip embeddings"""
    node_list = sorted(G.nodes())  # consistent order
    node_to_idx = {n: i for i, n in enumerate(node_list)}
    idx_to_node = {i: n for n, i in node_to_idx.items()}

    A = nx.to_scipy_sparse_array(G, nodelist=node_list, format='csr')
    L = csgraph.laplacian(A, normed=False)

    leaf_indices = [node_to_idx[n] for n in leaf_names]
    all_indices = np.arange(len(node_list))
    internal_indices = np.setdiff1d(all_indices, leaf_indices)

    # Create H_leaf matrix in node_list order
    D = len(H_leaf_dict.values())
    H_leaf = np.zeros((len(leaf_indices), D))
    for i, name in enumerate(leaf_names):
        H_leaf[i] = H_leaf_dict[name]


    L_II = csr_matrix(L.toarray()[np.ix_(internal_indices, internal_indices)])
    L_IL = csr_matrix(L.toarray()[np.ix_(internal_indices, leaf_indices)])

    H_internal = np.zeros((len(internal_indices), D))
    for d in range(D):
        rhs = -L_IL @ H_leaf[:, d]
        H_internal[:, d] = spsolve(L_II, rhs)

    H = np.zeros((len(node_list), D))
    H[leaf_indices] = H_leaf
    H[internal_indices] = H_internal

    return H, node_list  # matrix and node name order

