def tree_from_dirichlet(embeddings, node_order,n_leaves):

    current_leaves = set(range(n_leaves))

    max_coeffs = embeddings.argmax(axis = 1)
    value_counts = pd.Series(max_coeffs).value_counts()
    value_counts_ind = list(value_counts.index)

    i = 0

    while value_counts[i] > 1:

        repeated_leaves = torch.where(max_coeffs == value_counts_ind[i]).numpy()
        repeated_leaves = set(repeated_leaves.tolist())

        current_leaves = current_leaves.difference(repeated_leaves)

        current_leaves = current_leaves.add(value_counts_ind[i])



    return current_leaves
