def tree_from_dirichlet(embeddings, node_order,n_leaves):

    current_leaves = set(range(n_leaves))
    total_nodes = embeddings.shape[0]

    embeddings_zero = embeddings.clone()
    embeddings_zero[embeddings_zero == 1] = 0

    max_coeffs = embeddings_zero.argmax(axis = 0)
    value_counts = pd.Series(max_coeffs).value_counts()
    value_counts_ind = list(value_counts.index)

    for ind in value_counts_ind:

        if value_counts[ind] == 1:
            break

        repeated_leaves = torch.where(max_coeffs == ind)[0].numpy()
        repeated_leaves = set(repeated_leaves.tolist())

        current_leaves = current_leaves.difference(repeated_leaves)
        current_leaves.add(ind)

    while len(current_leaves) > 0:
         
        max_coeffs = []
        current_leaves = list(current_leaves)
        internal_nodes = list(set(total_nodes) - set(current_leaves))

        for node in internal_nodes:

            A = torch.transpose(embeddings[current_leaves, :]).numpy()
            b = torch.transpose(embeddings[node, :]).numpy()

            coeffs = np.linalg.solve(A,b)
            max_coeffs.append(current_leaves[coeffs.argmax()])

        max_coeffs = torch.tensor(max_coeffs)

        value_counts = pd.Series(max_coeffs).value_counts()
        value_counts_ind = list(value_counts.index)

        current_leaves = set(current_leaves)

        for ind in value_counts_ind:

            if value_counts[ind] == 1:
                break

            repeated_leaves = torch.where(max_coeffs == ind)[0].numpy()
            repeated_leaves = set(repeated_leaves.tolist())

            current_leaves = current_leaves.difference(repeated_leaves)
            current_leaves.add(ind)

    
    return current_leaves
