def node_embedding(tree, rooted = False):

    ntips = len(tree.get_leaves())
    leaf_features = torch.eye(ntips)
    counter = [0]

    for node in tree.traverse('postorder'):
        if node.is_leaf():
            node.c = 0
            node.d = leaf_features[counter[0]]
            counter[0] += 1
        else:
            child_c, child_d = 0., 0.
            for child in node.children:
                child_c += child.c
                child_d += child.d
            if node.is_root() and rooted:
                node.c = 1./(2. - child_c)
                node.d = node.c * child_d
            else:
                node.c = 1./(3. - child_c)
                node.d = node.c * child_d
        
    node_features, node_idx_list, edge_index = [], [], []    
    node_features_leaf, node_idx_list_leaf, edge_index_leaf = [], [], []   

    for node in tree.traverse('preorder'):
        neigh_idx_list = []
        if not node.is_root():
            node.d = node.c * node.up.d + node.d
            # parent_idx_list.append(node.up.name)
            neigh_idx_list.append(node.up.name)
            
            if not node.is_leaf():
                neigh_idx_list.extend([child.name for child in node.children])
            else:
                neigh_idx_list.extend([-1, -1])              
        else:
            if rooted:
                neigh_idx_list.extend([-1] + [child.name for child in node.children])
            else:
                neigh_idx_list.extend([child.name for child in node.children])
        
        if not node.is_leaf():
            edge_index.append(neigh_idx_list)                
            node_features.append(node.d)
            node_idx_list.append(node.name)
        else:
            edge_index_leaf.append(neigh_idx_list)                
            node_features_leaf.append(node.d)
            node_idx_list_leaf.append(node.name)
    
    edge_index = edge_index_leaf + edge_index
    node_features = node_features_leaf + node_features
    node_idx_list = node_idx_list_leaf + node_idx_list
    
    # branch_idx_map = torch.sort(torch.LongTensor(node_idx_list), dim=0, descending=False)[1]
    # parent_idxes = torch.LongTensor(parent_idx_list)
    edge_index = torch.LongTensor(edge_index)
    # pdb.set_trace()
    
    return torch.stack(node_features), edge_index, node_idx_list
