G, tree, node_taxa_mapping = newick_to_graph(tree_path)
sequences = [(record.description, remove_insertions(str(record.seq))) for record in SeqIO.parse(MSA_path, "fasta")]

n_sequences = len(sequences)

original_OHE = torch.eye(len(sequences))

