model, alphabet = esm.pretrained.esm_msa1b_t12_100M_UR50S()
model = model.to(device)
batch_converter = alphabet.get_batch_converter()
model.eval() 

_,_,batch_tokens = batch_converter([sequences])
batch_tokens = batch_tokens.to(device)

with torch.no_grad():
    embeddings = model(batch_tokens, need_head_weights = False, return_contacts = False, repr_layers = [12])["representations"][12][0]
    embeddings = embeddings.mean(dim=1)

del(batch_tokens, model, batch_converter, alphabet)
torch.cuda.empty_cache()

n_permutations = 100

X_train = [embeddings]
y_train = [original_OHE]

X_test = []
y_test = []

for i in range(n_permutations):

    ind_order = np.random.choice(range(n_sequences), n_sequences, replace=False)
    X_train.append(embeddings[ind_order])
    y_train.append(original_OHE[ind_order])

    ind_order = np.random.choice(range(n_sequences), n_sequences, replace=False)
    X_test.append(embeddings[ind_order])
    y_test.append(original_OHE[ind_order])

X_train = torch.stack(X_train, dim=0)
y_train = torch.stack(y_train, dim=0)

X_test = torch.stack(X_test, dim=0)
y_test = torch.stack(y_test, dim=0)

train_dataset = TensorDataset(X_train, y_train)
test_dataset = TensorDataset(X_test, y_test)

num_epochs = 50
batch_size = 1
learning_rate = 0.001

train_loader = torch.utils.data.DataLoader(dataset=train_dataset, 
                                        batch_size=batch_size, 
                                        shuffle=True)

test_loader = torch.utils.data.DataLoader(dataset=test_dataset, 
                                        batch_size=batch_size, 
                                        shuffle=False)


OHEmodel = OHEPredictor(input_size=768, hid_dim=500, output_dim=500).to(device=device)
criterion = nn.BCELoss()
optimizer = torch.optim.Adam(OHEmodel.parameters(), lr=learning_rate) 
scheduler = torch.optim.lr_scheduler.ExponentialLR(optimizer, gamma=0.95)

for param in OHEmodel.parameters():
    assert param.requires_grad   

n_samples_train = X_train.shape[0]
# n_samples_test = X_test.shape[0]

n_total_steps = len(train_loader)
print(n_total_steps)

train_epoch_losses = []
test_epoch_losses = []

for epoch in range(num_epochs):

    train_epoch_outputs = []
    train_labels = []

    OHEmodel.train()

    for i, (data, labels) in enumerate(train_loader):  

        data = data.to(device)
        labels = labels.to(device)

        outputs = OHEmodel(data).squeeze(1)[...,:len(labels[0])]

        loss = torch.tensor(0, dtype=torch.float64).to(device)
        
        for j in range(batch_size):

            loss += criterion(outputs[j], labels[j])

        optimizer.zero_grad()
        loss.backward()
        optimizer.step()

        train_epoch_outputs.append(outputs)
        train_labels.append(labels)
                
        if (i+1) % 10 == 0:
            print (f'Epoch [{epoch+1}/{num_epochs}], Step [{i+1}/{n_total_steps}], Loss: {loss.item():.4f}')

    scheduler.step()

    train_epoch_outputs = torch.cat(train_epoch_outputs)
    train_labels = torch.cat(train_labels)

    with torch.no_grad():
        train_epoch_loss = torch.tensor(0, dtype=torch.float64).to(device)
        
        for j in range(batch_size):

            loss += criterion(outputs[j], labels[j])

    train_epoch_losses.append(train_epoch_loss.item())

    OHEmodel.eval()

    test_epoch_outputs = []
    test_labels = []

    with torch.no_grad():

        for data, labels in test_loader:

            data = data.to(device)
            labels = labels.to(device)
            outputs = OHEmodel(data).squeeze(1)

            test_epoch_outputs.append(outputs)
            test_labels.append(labels)
        
        test_epoch_outputs = torch.cat(test_epoch_outputs)
        test_labels = torch.cat(test_labels)

        test_epoch_loss = 0
        
        for j in range(test_epoch_outputs):

            test_epoch_loss += criterion(test_epoch_outputs[j], test_labels[j])

        test_epoch_loss = test_epoch_loss.item()
        test_epoch_losses.append(test_epoch_loss)
