        outputs = OHEmodel(data).squeeze(1)[...,:len(labels[0])]

        # print(outputs)

        loss = torch.tensor(0, dtype=torch.float64).to(device)
        
        for j in range(batch_size):

            loss += criterion(outputs[j], labels[j]) +  0.01 * (torch.norm(outputs[j].sum(dim=0) - 1, p=2) + torch.norm(outputs[j].sum(dim=1) - 1, p=2))

        optimizer.zero_grad()
        loss.backward()
