def sample_gumbel(shape, eps=1e-20):
    U = torch.rand(shape)
    return -torch.log(-torch.log(U + eps) + eps)

def gumbel_sinkhorn(logits, n_iters=20, tau=1.0):
    gumbel_noise = sample_gumbel(logits.shape).to(logits.device)
    noisy_logits = (logits + gumbel_noise) / tau
    return sinkhorn(noisy_logits, n_iters)

def sinkhorn(logits, n_iters=20, eps=1e-8):
    logits = torch.exp(logits)
    for _ in range(n_iters):
        logits = logits / (logits.sum(dim=2, keepdim=True) + eps)  # row norm
        logits = logits / (logits.sum(dim=1, keepdim=True) + eps)  # col norm
    return logits
