n_total_steps = len(train_loader)

train_epoch_losses = []
test_epoch_losses = []

for epoch in range(num_epochs):

    train_epoch_outputs = []
    train_labels = []

    OHEmodel.train()

    for i, (data, labels) in enumerate(train_loader):  

        data = data.to(device)
        labels = labels.to(device)

        outputs = OHEmodel(data).squeeze(1)[...,:len(labels[0])]

        a = outputs.clone()

        print(outputs)

        loss = torch.tensor(0, dtype=torch.float64).to(device)
        
        soft_perm = gumbel_sinkhorn(outputs).clamp(min=1e-6, max=1-1e-6)

        b = soft_perm.clone()
        print(soft_perm)

        assert not pd.isna(soft_perm.max().item())
        
        for j in range(batch_size):

            loss += criterion(soft_perm[j], labels[j]) # + 1e-3 * (torch.norm(outputs[j].sum(dim=0) - 1, p=2) + torch.norm(outputs[j].sum(dim=1) - 1, p=2))

        optimizer.zero_grad()
        loss.backward()
        optimizer.step()

        train_epoch_outputs.append(outputs)
        train_labels.append(labels)
                
        if (i+1) % 10 == 0:
            print (f'Epoch [{epoch+1}/{num_epochs}], Step [{i+1}/{n_total_steps}], Loss: {loss.item():.4f}')

    scheduler.step()

    train_epoch_outputs = torch.cat(train_epoch_outputs)
    train_labels = torch.cat(train_labels)

    with torch.no_grad():
        train_epoch_loss = torch.tensor(0, dtype=torch.float64).to(device)

        soft_perm = gumbel_sinkhorn(train_epoch_outputs).clamp(min=1e-6, max=1-1e-6)
        
        for j in range(len(train_epoch_outputs)):

            train_epoch_loss += criterion(soft_perm[j], train_labels[j])

    train_epoch_losses.append(train_epoch_loss.item())

    OHEmodel.eval()

    test_epoch_outputs = []
    test_labels = []

    with torch.no_grad():

        for data, labels in test_loader:

            data = data.to(device)
            labels = labels.to(device)
            outputs = OHEmodel(data).squeeze(1)[...,:len(labels[0])]

            test_epoch_outputs.append(outputs)
            test_labels.append(labels)
        
        test_epoch_outputs = torch.cat(test_epoch_outputs)
        test_labels = torch.cat(test_labels)

        test_epoch_loss = 0

        soft_perm = gumbel_sinkhorn(test_epoch_outputs).clamp(min=1e-6, max=1-1e-6)
     
        for j in range(len(test_epoch_outputs)):

            test_epoch_loss += criterion(soft_perm[j], test_labels[j])

        test_epoch_loss = test_epoch_loss.item()
        test_epoch_losses.append(test_epoch_loss)
