def make_branch_lengths(tree):

    branch_lengths_dict = {}
    branch_lengths_list = []
    leaf_lengths_list = []

    for node in tree.traverse("preorder"):    
        if node.is_root():
            continue
        else:
            branch_length = node.get_distance(node.up)
            branch_lengths_dict[node.name] = branch_length

            if node.is_leaf():
                leaf_lengths_list.append(branch_length)
            else:
                branch_lengths_list.append(branch_length)
            

    branch_lengths_list = leaf_lengths_list + branch_lengths_list

    return branch_lengths_dict, branch_lengths_list
