test_loader = torch.utils.data.DataLoader(dataset=test_dataset, 
                                        batch_size=1, 
                                        collate_fn=collate_tensors,
                                        shuffle=False)

lr = 0.001
lamb = 0.01
num_epochs = 10000

model = ParentPredictor(1000, 512, 512, 16, 6, 1000).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr = lr)
scheduler = torch.optim.lr_scheduler.ExponentialLR(optimizer, gamma=0.99)
criterion = nn.CrossEntropyLoss()


n_total_steps = len(train_loader)

train_epoch_losses = []
test_epoch_losses = []

for epoch in range(num_epochs):

    train_epoch_outputs = []
    train_labels = []

    model.train()

    for i, (data, labels) in enumerate(train_loader):

        for j in range(len(data)):
            
            mask = (labels[j] != -1) 

            data_j = data[j][mask].to(device)
            labels_j = labels[j][mask].to(device)

            outputs = model(data_j)[...,:len(labels_j)]

            assert labels_j[1:].max() < len(labels_j)

            loss = criterion(outputs[1:], labels_j[1:])
            regularizer = lamb * torch.linalg.vector_norm(torch.softmax(outputs, dim = 1).sum(dim = 0) - 2).sum().type_as(loss)

            loss += regularizer

        optimizer.zero_grad()
        loss.backward()
        optimizer.step()

        if (i+1) % 1 == 0:
            print (f'Epoch [{epoch+1}/{num_epochs}], Step [{i+1}/{n_total_steps}], Loss: {loss.item():.4f}')

    scheduler.step()

    model.eval()

    with torch.no_grad():

        train_epoch_loss = torch.tensor(0, dtype=torch.float32).to(device)

                        
        for i, (data, labels) in enumerate(train_loader):
            
            for j in range(len(data)):
            
                mask = (labels[j] != -1) 

                data_j = data[j][mask].to(device)
                labels_j = labels[j][mask].to(device)

                outputs = model(data_j)[...,:len(labels_j)]
                
                assert labels_j[1:].max() < len(labels_j)

                train_epoch_loss += criterion(outputs[1:], labels_j[1:])

        train_epoch_losses.append(train_epoch_loss.item())

    with torch.no_grad():

        test_epoch_loss = torch.tensor(0, dtype=torch.float32).to(device)

        for i, (data, labels) in enumerate(test_loader):
            
            mask = (labels != -1) 

            data = data[mask].to(device)
            labels = labels[mask].to(device)

            outputs = model(data)[...,:len(labels)]
            test_epoch_loss += criterion(outputs[1:], labels[1:])

        test_epoch_losses.append(test_epoch_loss.mean().item())
