            data_j = data[j][mask].to(device)
            labels_j = labels[j][mask].to(device)

            n_int_nodes = int((len(labels_j) + 2)/2 - 1)

            outputs = model(data_j)[...,:n_int_nodes]

            assert labels_j[1:].max() < len(labels_j)

            cur_ce_loss = criterion(outputs[1:], labels_j[1:])
            # cur_regularizer_loss = lamb * torch.linalg.vector_norm(torch.softmax(outputs, dim = 1).sum(dim = 0) - 2).type_as(loss)

