train_dataset = TreeDataset((X_train, y_train_pc))
test_dataset = TreeDataset((X_test, y_test_pc))

train_loader = torch.utils.data.DataLoader(dataset=train_dataset, 
                                        batch_size=1, 
                                        collate_fn=collate_tensors,
                                        shuffle=True)

test_loader = torch.utils.data.DataLoader(dataset=test_dataset, 
                                        batch_size=1, 
                                        collate_fn=collate_tensors,
                                        shuffle=False)

lr = 0.0001
lamb = 0.1
num_epochs = 1000

model = ParentPredictor(1000, 512, 512, 16, 6, 1000).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr = lr)
scheduler = torch.optim.lr_scheduler.ExponentialLR(optimizer, gamma=0.999)
criterion = nn.CrossEntropyLoss()

n_total_steps = len(train_loader)

train_epoch_losses = []
test_epoch_losses = []

for epoch in range(num_epochs):

    train_epoch_outputs = []
    train_labels = []

    model.train()

    for i, (data, labels) in enumerate(train_loader):

        total_loss = torch.tensor(0, dtype=torch.float32).to(device)
        ce_loss = torch.tensor(0, dtype=torch.float32).to(device)
        regularizer_loss = torch.tensor(0, dtype=torch.float32).to(device)

        for j in range(len(data)):
            
            mask = (labels[j] != -1) 

            data_j = data[j][mask].to(device)
            labels_j = labels[j][mask].to(device)

            n_int_nodes = int((len(labels_j) + 2)/2 - 1)

            outputs = model(data_j)[...,:n_int_nodes]

            assert labels_j[1:].max() < len(labels_j)

            cur_ce_loss = criterion(outputs[1:], labels_j[1:])
            cur_regularizer_loss = lamb * torch.linalg.vector_norm(torch.softmax(outputs, dim = 1).sum(dim = 0) - 2).type_as(loss)

            total_loss += cur_ce_loss + cur_regularizer_loss
            ce_loss += cur_ce_loss
            regularizer_loss = cur_regularizer_loss

        optimizer.zero_grad()
        total_loss.backward()
        optimizer.step()

        if (i+1) % 1 == 0:
            print (f'Epoch [{epoch+1}/{num_epochs}], Step [{i+1}/{n_total_steps}], mean CE Loss: {(ce_loss/len(data)).item():.4f}')

    scheduler.step()

    model.eval()

    with torch.no_grad():

        train_epoch_loss = torch.tensor(0, dtype=torch.float32).to(device)
        n_train = 0
       
        for i, (data, labels) in enumerate(train_loader):
            
            for j in range(len(data)):
            
                mask = (labels[j] != -1) 

                data_j = data[j][mask].to(device)
                labels_j = labels[j][mask].to(device)

                n_int_nodes = int((len(labels_j) + 2)/2 - 1)

                outputs = model(data_j)[...,:n_int_nodes]
                
                assert labels_j[1:].max() < len(labels_j)

                train_epoch_loss += criterion(outputs[1:], labels_j[1:])
                n_train += 1

        train_epoch_losses.append((train_epoch_loss/n_train).item())

    with torch.no_grad():

        test_epoch_loss = torch.tensor(0, dtype=torch.float32).to(device)
        n_test = 0

        for i, (data, labels) in enumerate(test_loader):

            for j in range(len(data)):
            
                mask = (labels[j] != -1) 

                data_j = data[j][mask].to(device)
                labels_j = labels[j][mask].to(device)

                n_int_nodes = int((len(labels_j) + 2)/2 - 1)

                outputs = model(data_j)[...,:n_int_nodes]

                assert labels_j[1:].max() < len(labels_j)

                test_epoch_loss += criterion(outputs[1:], labels_j[1:])
                n_test += 1

        test_epoch_losses.append((test_epoch_loss/n_test).item())
